(function(){for(const row of window.BOOK2_VOCABULARY){const lesson=window.LESSONS.find(l=>l.id===row.lessonId);const item=lesson?.vocabulary.find(v=>v.word===row.word);if(item&&!item.meaning)Object.assign(item,{meaning:row.meaning,meaningSource:row.meaningSource,sourceType:row.sourceType,sourceLabel:row.sourceLabel,example:row.needsContextReview?'':row.example||item.example||'',needsContextReview:row.needsContextReview});}const contextualStatus=[];for(const row of window.BOOK2_CONTEXT_CORRECTIONS){const lesson=window.LESSONS.find(l=>l.id===row.lessonId&&l.book===2&&l.number===row.number);const item=lesson?.vocabulary.find(v=>v.word===row.word);if(!item||!lesson.paragraphs.some(p=>p.en.includes(row.contextSentence))){contextualStatus.push({id:row.id,status:'skipped-source-mismatch'});continue;}if(item[row.field]===row.newValue){contextualStatus.push({id:row.id,status:'already-current'});continue;}if(item[row.field]!==row.expectedOld){contextualStatus.push({id:row.id,status:'skipped-value-drift'});continue;}const originalItem=JSON.parse(JSON.stringify(item));item[row.field]=row.newValue;item.contextCorrections=(item.contextCorrections||[]).concat([{...row,originalItem}]);if(row.field==='meaning'){item.meaningSource='根据本课正文精确语境自编修正；非教材官方释义';item.sourceType=row.sourceType;item.sourceLabel=row.sourceLabel;item.example=row.contextSentence;item.exampleSourceType='lesson-passage';item.needsContextReview=false;}contextualStatus.push({id:row.id,status:'applied'});}window.BOOK2_CONTEXT_CORRECTION_STATUS=contextualStatus;window.BOOK2_VOCAB_STATUS={translated:window.BOOK2_VOCABULARY.length,unresolved:window.LESSONS.filter(l=>l.book===2).flatMap(l=>(l.vocabulary||[]).filter(v=>!v.meaning).map(v=>({lesson:l.number,word:v.word}))),contextReview:window.BOOK2_VOCABULARY.filter(v=>v.needsContextReview).map(v=>({lessonId:v.lessonId,word:v.word}))};})();
